import { Container, NineSliceSprite, Sprite } from 'pixi.js';

import { AssetManager } from '@game-studio/asset-manager';
import { Device } from '@game-studio/device';

import { CabinetButtonView } from './buttons/cabinet-button';
import { ActionButtonView } from './buttons/action-button-view';
import {
    CabinetLayoutState,
    CabinetUserPrefs,
    ICabinetInteractionMethods,
    IRequiredStrings,
    IStake,
    OneHandedPlaySetting,
    OneHandedPlaySettingStrings,
} from '../types/cabinet';
import { BalanceView } from './messages/balance-view';
import { MessageView } from './messages/message-view';
import { SharedMessageView } from './messages/shared-message-view';
import { HTPNudgeView } from './htp-info/htp-nudge';

export class CabinetView extends Container {
    private cabinetPadding: number = 3.5;
    private bottomSpacer: number = 5;

    private device: Device;
    private strings: IRequiredStrings;
    private interactionMethods: ICabinetInteractionMethods;

    private background: NineSliceSprite;

    private minusButtonView: CabinetButtonView;
    private actionButtonView: ActionButtonView;
    private plusButtonView: CabinetButtonView;
    private messageView: MessageView;
    private balanceView: BalanceView;
    private settingsButtonView: CabinetButtonView;
    private infoButtonView: CabinetButtonView;
    private htpNudgeView: HTPNudgeView;
    private divider: Sprite;

    private cabinetButtons: CabinetButtonView[] = [];

    private oneHandedSetting: OneHandedPlaySetting | OneHandedPlaySettingStrings;
    private activeLayout: CabinetLayoutState = 'floating';
    private _isScalingLayoutEnabled: boolean = true;
    private floatingActionButtonPortraitWidthFraction: number = 0.12;
    private floatingActionButtonGapMultiplier: number = 0.3;

    public getStake: () => IStake;

    /** @deprecated `buyButton` is no longer supported. Please use `actionButton` instead. */
    public get buyButton(): ActionButtonView {
        return this.actionButtonView;
    }
    public get backgroundWidth(): number {
        return this.background.width;
    }
    public get backgroundHeight(): number {
        return this.background.height;
    }
    public get settingsButton(): CabinetButtonView {
        return this.settingsButtonView;
    }
    public get infoButton(): CabinetButtonView {
        return this.infoButtonView;
    }
    public get decreaseStakeButton(): CabinetButtonView {
        return this.minusButtonView;
    }
    public get increaseStakeButton(): CabinetButtonView {
        return this.plusButtonView;
    }
    public get actionButton(): ActionButtonView {
        return this.actionButtonView;
    }
    public get messageComponent(): MessageView {
        return this.messageView;
    }
    public get balanceComponent(): BalanceView {
        return this.balanceView;
    }
    public get htpNudge(): HTPNudgeView {
        return this.htpNudgeView;
    }

    /**
     * Returns the physical dimensions of the cabinet
     *
     * Position is based on the top left corner
     *
     * Anchored state excludes the action button
     *
     * Floating state includes the action button
     */
    public get dimensions() {
        if (this.activeLayout === 'floating') {
            return {
                x: this.x,
                y: this.y + this.actionButtonView.y - this.actionButtonView.buttonSpriteHeight * 0.5,
                width: this.width,
                height: this.background.height + -this.actionButtonView.y + this.actionButtonView.buttonSpriteHeight * 0.5,
            };
        } else {
            return {
                x: this.x,
                y: this.y,
                width: this.width,
                height: this.background.height,
            };
        }
    }

    public set oneHandedPlaySetting(value: OneHandedPlaySetting | OneHandedPlaySettingStrings) {
        this.oneHandedSetting = value;
        this.updateLayout();
    }

    private get isDesktop(): boolean {
        return this.device.type.isDesktop;
    }
    private get cabinetHeightMulti(): number {
        return this.device.orientation.isLandscape ? 0.08 : 0.036;
    }
    private get cabinetWidthMulti(): number {
        return this.isDesktop ? 0.85 : 0.95;
    }
    private get isMobilePortrait(): boolean {
        return this.device.type.isMobile && this.device.orientation.isPortrait;
    }
    private get isLeftHanded(): boolean {
        return (
            this.isDesktop === false &&
            (this.oneHandedSetting === OneHandedPlaySetting.left || this.oneHandedSetting === OneHandedPlaySettingStrings.left)
        );
    }
    private get centerY(): number {
        return this.background.height * 0.5;
    }
    private get edgeButtonGap(): number {
        return this.cabinetPadding * 2;
    }
    private get leftGroupButtonGap(): number {
        return this.edgeButtonGap * (this.isMobilePortrait ? 1.5 : 2);
    }
    private get rightGroupButtonGap(): number {
        return this.device.orientation.isLandscape ? this.edgeButtonGap * 0.75 : this.edgeButtonGap * 0.25;
    }
    private get dividerGap(): number {
        return this.edgeButtonGap * (this.isMobilePortrait ? 1.25 : 1.5);
    }
    private get maxMessageHeight(): number {
        return this.background.height * 0.95;
    }

    constructor(
        device: Device,
        strings: IRequiredStrings,
        interactionMethods: ICabinetInteractionMethods,
        userPrefs: CabinetUserPrefs,
        getStake: () => IStake,
    ) {
        super();

        this.device = device;
        this.strings = strings;
        this.interactionMethods = interactionMethods;
        this.oneHandedSetting = userPrefs.oneHandedPlay;
        this.getStake = getStake;

        this.createComponents();

        this.addChild(...this.cabinetButtons);
    }

    public showStakeButtons(show: boolean): void {
        this.minusButtonView.visible = this.minusButtonView.renderable = show;
        this.plusButtonView.visible = this.plusButtonView.renderable = show;
    }

    public showActionButton(show: boolean): void {
        this.actionButtonView.visible = this.actionButtonView.renderable = show;
    }

    public set isScalingLayoutEnabled(value: boolean) {
        this._isScalingLayoutEnabled = value;
    }

    public set scalingLayoutWidthFraction(value: number) {
        this.floatingActionButtonPortraitWidthFraction = value;
    }
    public set scalingLayoutGapMultiplier(value: number) {
        this.floatingActionButtonGapMultiplier = value;
    }

    public onOrientationChange(gameWidth: number, gameHeight: number): void {
        this.actionButtonView.onOrientationChange();
        this.sizeBackground(gameWidth, gameHeight);
        this.scaleButtons(gameWidth);
        this.scaleDivider();
        this.updatePosition(gameWidth, gameHeight);
        this.updateLayout();
    }

    public setLayout(layout: CabinetLayoutState): void {
        this.activeLayout = layout;
        this.actionButtonView.setMode(layout);

        this.updateLayout();
    }

    private createComponents(): void {
        this.createBackground();

        // Create Left Side Buttons
        this.createSettingsButton();
        this.createInfoButton();
        this.createHtpBubble();

        this.createDivider();
        this.createMessageView();
        this.createBalanceView();

        // Create Right Side Buttons
        this.createMinusButton();
        this.createPlusButton();
        this.createActionButton();

        this.settingsButtonView.name = 'cabinet-settings-button';
        this.infoButtonView.name = 'cabinet-game-info-button';
        this.minusButtonView.name = 'cabinet-decrease-stake-button';
        this.plusButtonView.name = 'cabinet-increase-stake-button';
        this.actionButtonView.name = 'cabinet-action-button';

        this.background.name = 'cabinet-background';
        this.divider.name = 'cabinet-divider';
    }

    private createBackground(): void {
        const horiztonalCutoffValue = 39;
        const sideCutoffValue = 237;

        this.background = new NineSliceSprite({
            texture: AssetManager.getTexture('cabinet-background'),
            leftWidth: sideCutoffValue,
            topHeight: horiztonalCutoffValue,
            rightWidth: sideCutoffValue,
            bottomHeight: horiztonalCutoffValue
        });

        this.addChild(this.background);
    }

    private createSettingsButton(): void {
        this.settingsButtonView = new CabinetButtonView(AssetManager.getTexture('settings-button'), [
            { pointerEvent: 'pointerup', callback: this.interactionMethods.onSettingsButtonClick },
        ]);

        this.cabinetButtons.push(this.settingsButtonView);
    }

    private createInfoButton(): void {
        this.infoButtonView = new CabinetButtonView(AssetManager.getTexture('info-button'), [
            { pointerEvent: 'pointerup', callback: this.interactionMethods.onGameInfoClick },
        ]);

        this.cabinetButtons.push(this.infoButtonView);
    }

    private createHtpBubble(): void {
        this.htpNudgeView = new HTPNudgeView(this.strings.htpNudgeLabel);

        this.addChild(this.htpNudgeView);
    }

    private createMinusButton(): void {
        this.minusButtonView = new CabinetButtonView(AssetManager.getTexture('minus-button'), [
            { pointerEvent: 'pointerup', callback: this.interactionMethods.onDecreaseStakeClick },
            { pointerEvent: 'pointerup', callback: this.onStakeButtonClick.bind(this) },
        ]);

        this.cabinetButtons.push(this.minusButtonView);
    }

    private createPlusButton(): void {
        this.plusButtonView = new CabinetButtonView(AssetManager.getTexture('plus-button'), [
            { pointerEvent: 'pointerup', callback: this.interactionMethods.onIncreaseStakeClick },
            { pointerEvent: 'pointerup', callback: this.onStakeButtonClick.bind(this) },
        ]);

        this.cabinetButtons.push(this.plusButtonView);
    }

    private createActionButton(): void {
        this.actionButtonView = new ActionButtonView(this.activeLayout, AssetManager.getTexture('action-button'), [
            { pointerEvent: 'pointertap', callback: this.interactionMethods.onActionButtonClick },
            { pointerEvent: 'pointerdown', callback: this.interactionMethods.onActionButtonHold },
            { pointerEvent: 'pointerup', callback: this.interactionMethods.onActionButtonHoldEnd },
            { pointerEvent: 'pointerupoutside', callback: this.interactionMethods.onActionButtonHoldEndOutside },
        ]);

        this.cabinetButtons.push(this.actionButtonView);
    }

    private createDivider(): void {
        this.divider = new Sprite(AssetManager.getTexture('cabinet-divider'));
        this.divider.anchor.set(0.5);

        this.addChild(this.divider);
    }

    private createMessageView(): void {
        this.messageView = new MessageView(this.device);

        this.addChild(this.messageView);
    }

    private createBalanceView(): void {
        this.balanceView = new BalanceView(this.device, this.strings);

        this.addChild(this.balanceView);
    }

    private sizeBackground(gameWidth: number, gameHeight: number): void {
        const maxCabinetWidth = 900;
        const cabinetWidth = Math.min(gameWidth * this.cabinetWidthMulti, maxCabinetWidth);
        const minHeight = this.isDesktop ? 42 : 35;
        const maxHeight = gameHeight * 0.125; // may be smaller than minHeight but takes precedence to avoid covering too much of the game view
        const targetHeight = this.device.viewport.height * this.cabinetHeightMulti;
        const cabinetHeight = Math.min(Math.max(minHeight, targetHeight), maxHeight);

        this.background.height = cabinetHeight;
        this.background.width = cabinetWidth;
    }

    private updatePosition(gameWidth: number, gameHeight: number): void {
        const xPosition = (gameWidth - this.background.width) * 0.5;
        const yPosition = gameHeight - this.background.height - this.bottomSpacer;
        this.position.set(xPosition, yPosition);
    }

    private scaleButtons(gameWidth: number): void {
        const buttonHeight = this.background.height * 0.75;

        this.cabinetButtons.forEach((cabinetButtonView) => {
            const scale = buttonHeight / cabinetButtonView.dimensions.height;
            cabinetButtonView.scale.set(scale);
        });

        if (this.activeLayout === 'floating') {
            const actionBtnHeight = this._isScalingLayoutEnabled
                ? gameWidth * this.floatingActionButtonPortraitWidthFraction
                : this.background.height * 2.9;
            const actionBtnScale = actionBtnHeight / this.actionButtonView.dimensions.height;
            this.actionButtonView.updateScale(actionBtnScale);

            const stakeBtnHeight = actionBtnHeight * 0.4;
            const stakeBtnScale = stakeBtnHeight / this.decreaseStakeButton.dimensions.height;
            this.decreaseStakeButton.scale.set(stakeBtnScale);
            this.increaseStakeButton.scale.set(stakeBtnScale);
        } else {
            const actionBtnScalar = this.isMobilePortrait ? 1.8 : 2.2;
            const actionBtnHeight = this.background.height * actionBtnScalar;
            const actionBtnScale = actionBtnHeight / this.actionButtonView.dimensions.height;
            const actionBtnScaleDisabled = buttonHeight / this.actionButtonView.dimensions.height;
            this.actionButtonView.updateScale(actionBtnScale, actionBtnScaleDisabled);
        }
    }

    private scaleDivider(): void {
        const dividerHeightPercentage = 0.6;
        const dividerHeight = this.background.height * dividerHeightPercentage;

        this.divider.height = dividerHeight;
        this.divider.scale.x = this.divider.scale.y;
    }

    private layoutUtilityButtons(): void {
        if (this.isLeftHanded) {
            // Left Handed - Reverse order of buttons
            const settingsX = this.background.width - (this.edgeButtonGap + this.settingsButtonView.width * 0.5);
            this.settingsButtonView.position.set(settingsX, this.centerY);

            const infoX = this.settingsButtonView.x - this.settingsButtonView.width * 0.5 - this.leftGroupButtonGap - this.infoButtonView.width * 0.5;
            this.infoButtonView.position.set(infoX, this.centerY);

            // HTP Nudge - size based on distance from info button center to right edge
            const nudgeWidth = (this.background.width - infoX) * 2;
            const nudgeHeight = this.infoButtonView.height * 1.5;
            this.htpNudgeView.resize(nudgeWidth, nudgeHeight);
            // Position above info button
            this.htpNudgeView.position.set(infoX, 0);

            const dividerX = infoX - this.infoButtonView.width * 0.5 - this.dividerGap;
            this.divider.position.set(dividerX, this.centerY);
        } else {
            const settingsX = this.edgeButtonGap + this.settingsButtonView.width * 0.5;
            this.settingsButtonView.position.set(settingsX, this.centerY);

            const infoX = this.settingsButtonView.x + this.settingsButtonView.width * 0.5 + this.leftGroupButtonGap + this.infoButtonView.width * 0.5;
            this.infoButtonView.position.set(infoX, this.centerY);

            // HTP Nudge - size based on distance from info button center to left edge
            const nudgeWidth = infoX * 2;
            const nudgeHeight = this.infoButtonView.height * 1.5;
            this.htpNudgeView.resize(nudgeWidth, nudgeHeight);
            // Position above info button
            this.htpNudgeView.position.set(infoX, 0);

            const dividerX = infoX + this.infoButtonView.width * 0.5 + this.dividerGap;
            this.divider.position.set(dividerX, this.centerY);
        }
    }

    private layoutStakeAndActionButtons(): void {
        if (this.activeLayout === 'floating') {
            const actionXPosition = this.background.width * 0.5;
            const actionButtonScaledHeight = this.actionButtonView.buttonSpriteHeight;
            const actionYPosition = -(actionButtonScaledHeight * (0.5 + this.floatingActionButtonGapMultiplier));

            this.actionButtonView.position.set(actionXPosition, actionYPosition);

            const offsetFromActionButton = this.actionButtonView.defaultScaledWidth * 0.65;
            // Minus on left of action button, Plus on right
            const minusX = actionXPosition - offsetFromActionButton - this.minusButtonView.width * 0.5;
            this.minusButtonView.position.set(minusX, actionYPosition);

            const plusX = actionXPosition + offsetFromActionButton + this.plusButtonView.width * 0.5;
            this.plusButtonView.position.set(plusX, actionYPosition);
        } else if (this.isLeftHanded) {
            // Left-handed inline layouts
            if (this.isMobilePortrait) {
                // Mobile portrait with chat visible - Minus -> Action -> Plus (from left)
                let x = this.edgeButtonGap + this.minusButtonView.width * 0.5;
                this.minusButtonView.position.set(x, this.centerY);

                x += this.minusButtonView.width * 0.5 + this.rightGroupButtonGap + this.actionButtonView.defaultScaledWidth * 0.5;
                this.actionButtonView.position.set(x, this.centerY);

                x += this.actionButtonView.defaultScaledWidth * 0.5 + this.rightGroupButtonGap + this.plusButtonView.width * 0.5;
                this.plusButtonView.position.set(x, this.centerY);
            } else {
                // Desktop - Minus -> Action -> Plus (from left)
                let x = this.edgeButtonGap + this.minusButtonView.width * 0.5;
                this.minusButtonView.position.set(x, this.centerY);

                x += this.minusButtonView.width * 0.5 + this.rightGroupButtonGap + this.actionButtonView.defaultScaledWidth * 0.5;
                this.actionButtonView.position.set(x, this.centerY);

                x += this.actionButtonView.defaultScaledWidth * 0.5 + this.rightGroupButtonGap + this.plusButtonView.width * 0.5;
                this.plusButtonView.position.set(x, this.centerY);
            }
        } else {
            // Right-handed inline layouts
            if (this.isMobilePortrait) {
                // Mobile portrait with chat visible - Plus -> Action -> Minus (from right)
                let x = this.background.width - (this.edgeButtonGap + this.plusButtonView.width * 0.5);
                this.plusButtonView.position.set(x, this.centerY);

                x -= this.plusButtonView.width * 0.5 + this.rightGroupButtonGap + this.actionButtonView.defaultScaledWidth * 0.5;
                this.actionButtonView.position.set(x, this.centerY);

                x -= this.actionButtonView.defaultScaledWidth * 0.5 + this.rightGroupButtonGap + this.minusButtonView.width * 0.5;
                this.minusButtonView.position.set(x, this.centerY);
            } else {
                // Desktop - Plus -> Action -> Minus (from right to left)
                const plusX = this.background.width - (this.edgeButtonGap + this.plusButtonView.width * 0.5);
                this.plusButtonView.position.set(plusX, this.centerY);

                const actionX = plusX - this.plusButtonView.width * 0.5 - this.rightGroupButtonGap - this.actionButtonView.defaultScaledWidth * 0.5;
                this.actionButtonView.position.set(actionX, this.centerY);

                const minusX = actionX - this.actionButtonView.defaultScaledWidth * 0.5 - this.rightGroupButtonGap - this.minusButtonView.width * 0.5;
                this.minusButtonView.position.set(minusX, this.centerY);
            }
        }
    }

    private layoutMessageViews(): void {
        // Single percentage for balance view
        const gapPercentage = 0.02;
        const balanceViewWidthPercentage = 0.45;
        const messageViewWidthPercentage = 1 - balanceViewWidthPercentage - gapPercentage;

        if (this.isLeftHanded) {
            const dividerLeftEdge = this.divider.x - this.divider.width * 0.5;
            const leftEdge = this.activeLayout === 'floating' ? this.edgeButtonGap : this.plusButtonView.x + this.plusButtonView.width * 0.5;

            const availableMessageAreaWidth = dividerLeftEdge - leftEdge - this.dividerGap * 2;

            // Calculate widths
            const maxBalanceWidth = availableMessageAreaWidth * balanceViewWidthPercentage;
            const maxMessageWidth = availableMessageAreaWidth * messageViewWidthPercentage;

            // Calculate X positions so each view is centered in its area
            const messageX = leftEdge + this.dividerGap;
            const balanceX = dividerLeftEdge - this.dividerGap;

            // Set dimensions and positions
            this.messageView.setMaxDimensions(maxMessageWidth, this.maxMessageHeight);
            this.messageView.position.set(messageX, this.centerY - this.maxMessageHeight * 0.54);

            this.balanceView.setMaxDimensions(maxBalanceWidth, this.maxMessageHeight);
            this.balanceView.position.set(balanceX, this.centerY - this.maxMessageHeight * 0.54);
        } else {
            const dividerRightEdge = this.divider.x + this.divider.width * 0.5;
            const rightEdge =
                this.activeLayout === 'floating'
                    ? this.background.width - this.edgeButtonGap
                    : this.minusButtonView.x - this.minusButtonView.width * 0.5;

            const availableMessageAreaWidth = rightEdge - dividerRightEdge - this.dividerGap * 2;

            // Calculate widths
            const maxBalanceWidth = availableMessageAreaWidth * balanceViewWidthPercentage;
            const maxMessageWidth = availableMessageAreaWidth * messageViewWidthPercentage;

            // Calculate X positions so each view is centered in its area
            const balanceX = dividerRightEdge + this.dividerGap;
            const messageX = rightEdge - this.dividerGap;

            // Set dimensions and positions
            this.balanceView.setMaxDimensions(maxBalanceWidth, this.maxMessageHeight);
            this.balanceView.position.set(balanceX, this.centerY - this.maxMessageHeight * 0.54);

            this.messageView.setMaxDimensions(maxMessageWidth, this.maxMessageHeight);
            this.messageView.position.set(messageX, this.centerY - this.maxMessageHeight * 0.54);
        }

        this.messageView.updateLayoutStyle();
        this.balanceView.updateLayoutStyle();
    }

    private updateLayout(): void {
        this.messageView.isLeftHandedMode = this.isLeftHanded;
        this.balanceView.isLeftHandedMode = this.isLeftHanded;

        SharedMessageView.resetSharedScale();

        this.layoutUtilityButtons();
        this.layoutStakeAndActionButtons();
        this.layoutMessageViews();

        const cabinetBottom = { x: 0, y: this.background.height };
        this.actionButtonView.updateYOffset(cabinetBottom, this);
    }

    private onStakeButtonClick(): void {
        this.actionButtonView.updateStakeText(this.getStake().stake);
    }
}
